export const GRID_SIZE = 100;
export const GRID_COLS = 6;
export const GRID_ROWS = 8;
export const GRID_ORIGIN_X = -GRID_COLS * GRID_SIZE / 2;   // -300
export const GRID_ORIGIN_Y = -GRID_ROWS * GRID_SIZE / 2;   // -400

export function gridToWorld(gridX: number, gridY: number): { x: number; y: number } {
    return {
        x: GRID_ORIGIN_X + (gridX + 0.5) * GRID_SIZE,
        y: GRID_ORIGIN_Y + (gridY + 0.5) * GRID_SIZE,
    };
}

export function worldToGrid(wx: number, wy: number): { gridX: number; gridY: number } | null {
    const gx = Math.floor((wx - GRID_ORIGIN_X) / GRID_SIZE);
    const gy = Math.floor((wy - GRID_ORIGIN_Y) / GRID_SIZE);
    if (gx < 0 || gx >= GRID_COLS || gy < 0 || gy >= GRID_ROWS) return null;
    return { gridX: gx, gridY: gy };
}